files.Makefile:
# AgentHub - Multi-Agent Programming Collaboration Tool
# Makefile for building Electron app and DMG

.PHONY: all clean install build dev electron dist dmg help

# Default target
all: build

# Help target
help:
	@echo "AgentHub Build System"
	@echo "===================="
	@echo ""
	@echo "Available targets:"
	@echo "  install            - Install all dependencies"
	@echo "  dev                - Start development servers"
	@echo "  build              - Build frontend and backend"
	@echo "  build-frontend     - Build frontend only"
	@echo "  electron           - Run Electron app (requires frontend dev server)"
	@echo "  electron-standalone- Run Electron app with built frontend"
	@echo "  dist               - Build production Electron app"
	@echo "  dmg                - Build macOS DMG installer"
	@echo "  clean              - Clean build artifacts"
	@echo "  help               - Show this help message"

# Install dependencies
install:
	@echo "Installing dependencies..."
	npm install
	cd frontend && npm install
	cd backend && npm install

# Development
dev:
	@echo "Starting development servers..."
	@echo "Backend will start on port 8080"
	@echo "Frontend will start on port 3000"
	@echo "Press Ctrl+C to stop"
	make -j2 dev-backend dev-frontend

dev-backend:
	cd backend && npm run dev

dev-frontend:
	cd frontend && npm run dev

# Run Electron in development
electron:
	@echo "Starting Electron in development mode..."
	npm run electron:dev

# Run Electron standalone (with built frontend)
electron-standalone: build-frontend
	@echo "Starting Electron with built frontend..."
	npm run electron:dev

# Build frontend only
build-frontend:
	@echo "Building frontend..."
	cd frontend && npm run build

# Build everything
build:
	@echo "Building frontend and backend..."
	npm run build:frontend
	npm run build:backend

# Build Electron app for distribution
dist: build
	@echo "Building Electron app for distribution..."
	npm run dist

# Build macOS DMG (frontend-only)
dmg: build-frontend
	@echo "Building macOS DMG installer..."
	npm run dist:mac

# Clean build artifacts
clean:
	@echo "Cleaning build artifacts..."
	rm -rf dist/
	rm -rf frontend/dist/
	rm -rf backend/dist/
	rm -rf node_modules/
	rm -rf frontend/node_modules/
	rm -rf backend/node_modules/

# Create app icon (requires iconutil on macOS)
icon:
	@echo "Creating app icon..."
	mkdir -p assets/icon.iconset
	# Add different sizes of your icon PNG files to assets/icon.iconset/
	# icon_16x16.png, icon_32x32.png, icon_128x128.png, icon_256x256.png, icon_512x512.png, icon_1024x1024.png
	# Then run: iconutil -c icns assets/icon.iconset -o assets/icon.icns

# Quick test build
test-build: clean install build

# Full release build
release: clean install build dmg
	@echo "Release build complete! Check dist/ folder for DMG file."

# Development workflow
quick-start: install
	@echo "Quick start: Installing and launching development environment..."
	make -j2 dev-backend electron

# Check system requirements
check:
	@echo "Checking system requirements..."
	@node --version || (echo "Node.js not found. Please install Node.js 18+"; exit 1)
	@npm --version || (echo "npm not found. Please install npm"; exit 1)
	@echo "System requirements OK"

# Setup development environment
setup: check install
	@echo "Development environment setup complete!"
	@echo "Run 'make dev' to start development servers"
	@echo "Run 'make electron' to start Electron app"

.DEFAULT_GOAL := help

BINARY_NAME := updo
LAMBDA_BINARY := aws/bootstrap
LAMBDA_ZIP := aws/bootstrap.zip
LAMBDA_SOURCE := lambda/lambda.go

GOOS := linux
GOARCH := arm64
CGO_ENABLED := 0
BUILD_TAGS := lambda.norpc

.PHONY: help doctor build-lambda build clean test lint vet format check install

help: ## Show usage and commands
	@printf "updo - Website monitoring tool with multi-region Lambda support\n\n"
	@printf "Usage: make <command>\n\n"
	@printf "Commands:\n"
	@grep -E '^[a-zA-Z_-]+:.*?## .*$$' $(MAKEFILE_LIST) | \
		awk 'BEGIN {FS = ":.*?## "}; {printf "  %-12s %s\n", $$1, $$2}'
	@printf "\nExamples:\n"
	@printf "  make doctor                    # Check prerequisites\n"
	@printf "  make build                     # Build updo binary with embedded Lambda\n"
	@printf "  make test                      # Build and test deployment\n"
	@printf "  make clean                     # Remove build artifacts\n"

doctor: ## Check required tools and environment
	@echo "Checking prerequisites..."
	@if ! command -v go >/dev/null 2>&1; then \
		echo "Error: Go not found in PATH"; exit 1; \
	fi
	@echo "OK: Go found ($$(go version))"
	@if ! command -v zip >/dev/null 2>&1; then \
		echo "Error: zip not found in PATH"; exit 1; \
	fi
	@echo "OK: zip found"
	@if ! go mod verify >/dev/null 2>&1; then \
		echo "Error: Go modules not valid - run 'go mod tidy'"; exit 1; \
	fi
	@echo "OK: Go modules verified"
	@if [ ! -f "$(LAMBDA_SOURCE)" ]; then \
		echo "Error: Lambda source not found at $(LAMBDA_SOURCE)"; exit 1; \
	fi
	@echo "OK: Lambda source found"
	@echo "All prerequisites satisfied!"

build-lambda: ## Build Lambda binary for embedding
	@echo "Building Lambda binary for ARM64..."
	@cd lambda && GOOS=$(GOOS) GOARCH=$(GOARCH) CGO_ENABLED=$(CGO_ENABLED) \
		go build -tags $(BUILD_TAGS) -ldflags="-s -w" -o ../$(LAMBDA_BINARY) $(notdir $(LAMBDA_SOURCE))
	@echo "Lambda binary built: $(LAMBDA_BINARY)"
	@echo "Creating ZIP archive for embedding..."
	@cd aws && zip -q bootstrap.zip bootstrap
	@echo "Lambda ZIP created: $(LAMBDA_ZIP)"

build: build-lambda ## Build updo binary with embedded Lambda
	@echo "Building $(BINARY_NAME) with embedded Lambda binary..."
	@go build -ldflags="-s -w" -o $(BINARY_NAME) .
	@echo "Binary built: $(BINARY_NAME)"

install: build ## Install updo binary to GOPATH/bin
	@echo "Installing $(BINARY_NAME) to GOPATH/bin..."
	@go install .
	@echo "$(BINARY_NAME) installed successfully"

test: build ## Build and test deployment with dry-run
	@echo "Testing deployment with dry-run..."
	@./$(BINARY_NAME) aws deploy --dry-run
	@echo "Test completed successfully"

lint: ## Run golangci-lint if available
	@if command -v golangci-lint >/dev/null 2>&1; then \
		echo "Running golangci-lint..."; \
		golangci-lint run; \
	else \
		echo "Warning: golangci-lint not found, skipping lint check"; \
	fi

vet: ## Run go vet
	@echo "Running go vet..."
	@go vet ./...

format: ## Format code with gofmt
	@echo "Formatting code..."
	@gofmt -s -w .
	@cd lambda && gofmt -s -w .

check: vet lint ## Run all code quality checks
	@echo "All checks completed"

clean: ## Remove all build artifacts
	@echo "Cleaning build artifacts..."
	@rm -f $(BINARY_NAME) $(LAMBDA_BINARY) $(LAMBDA_ZIP)
	@echo "Clean completed"
